def smallestSubarrays(nums: list[int]) -> list[int]:
    n = len(nums)
    last_pos = [-1] * 32
    ans = [1] * n
    for i in range(n - 1, -1, -1):
        for b in range(32):
            if (nums[i] >> b) & 1:
                last_pos[b] = i
        max_reach = max([last_pos[b] for b in range(32) if last_pos[b] != -1], default=i)
        ans[i] = max(1, max_reach - i + 1)
    return ans

